class Solution:
    def searchMatrix(self, matrix: list[list[int]], target: int) -> bool:
        m, n = len(matrix), len(matrix[0])
        lo, hi = 0, m * n - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            r, c = divmod(mid, n)
            row = matrix[r]
            if row[c] == target:  # viz:check
                return True  # viz:found
            if row[c] < target:
                lo = mid + 1  # viz:right
            else:
                hi = mid - 1  # viz:left
        return False  # viz:done
